// ============================================================================
// Types
// ============================================================================

export interface SimpleLendingLoan {
  borrower: Hex
  lender: Hex
  collateralToken: Hex
  loanToken: Hex
  collateralAmount: bigint
  loanAmount: bigint
  interestRate: bigint // basis points (100 = 1%)
  duration: bigint // seconds
  startTime: bigint
  isActive: boolean
  isFunded: boolean
  borrowerIBCAddr: string
  borrowerChannel: string
  lenderIBCAddr: string
  lenderChannel: string
}

export interface SimpleLendingLoanWithId extends SimpleLendingLoan {
  id: bigint
  // Computed fields (populated by hooks)
  isExpired?: boolean
  currentInterest?: bigint
}

export type LoanStatus =
  | 'unfunded'
  | 'active'
  | 'expired'
  | 'repaid'
  | 'liquidated'
  | 'cancelled'

// ============================================================================
// Contract Bytecode
// ============================================================================

export const SIMPLE_LENDING_BYTECODE: Hex =
  ''

// ============================================================================
// Memo Creation Functions (for IBC execution via EEM)
// ============================================================================

/**
 * Creates a memo for creating a loan via IBC.
 * Encodes: approve(collateralToken) + createLoan
 */
export function createCreateLoanMemo(
  lendingContract: Hex,
  collateralToken: Hex,
  collateralAmount: bigint,
  loanToken: Hex,
  loanAmount: bigint,
  interestRate: bigint,
  duration: bigint
): string {
  const approveCalldata = encodeFunctionData({
    abi: ERC20_APPROVE_ABI,
    functionName: 'approve',
    args: [lendingContract, collateralAmount],
  })

  const createLoanCalldata = encodeFunctionData({
    abi: SIMPLE_LENDING_ABI,
    functionName: 'createLoan',
    args: [
      collateralToken,
      loanToken,
      collateralAmount,
      loanAmount,
      interestRate,
      duration,
    ],
  })

  return createEEMMemo([
    { contract: collateralToken, calldata: approveCalldata, is_payable: false },
    {
      contract: lendingContract,
      calldata: createLoanCalldata,
      is_payable: false,
    },
  ])
}

/**
 * Creates a memo for funding a loan via IBC.
 * Encodes: approve(loanToken) + fundLoan
 */
export function createFundLoanMemo(
  lendingContract: Hex,
  loanToken: Hex,
  loanAmount: bigint,
  loanId: bigint
): string {
  const approveCalldata = encodeFunctionData({
    abi: ERC20_APPROVE_ABI,
    functionName: 'approve',
    args: [lendingContract, loanAmount],
  })

  const fundLoanCalldata = encodeFunctionData({
    abi: SIMPLE_LENDING_ABI,
    functionName: 'fundLoan',
    args: [loanId],
  })

  return createEEMMemo([
    { contract: loanToken, calldata: approveCalldata, is_payable: false },
    { contract: lendingContract, calldata: fundLoanCalldata, is_payable: false },
  ])
}

/**
 * Creates a memo for repaying a loan via IBC.
 * Encodes: approve(loanToken for repayment amount) + repayLoan
 */
export function createRepayLoanMemo(
  lendingContract: Hex,
  loanToken: Hex,
  repaymentAmount: bigint,
  loanId: bigint
): string {
  const approveCalldata = encodeFunctionData({
    abi: ERC20_APPROVE_ABI,
    functionName: 'approve',
    args: [lendingContract, repaymentAmount],
  })

  const repayLoanCalldata = encodeFunctionData({
    abi: SIMPLE_LENDING_ABI,
    functionName: 'repayLoan',
    args: [loanId],
  })

  return createEEMMemo([
    { contract: loanToken, calldata: approveCalldata, is_payable: false },
    {
      contract: lendingContract,
      calldata: repayLoanCalldata,
      is_payable: false,
    },
  ])
}

/**
 * Creates a memo for liquidating an expired loan via IBC.
 * Encodes: liquidate (no token approval needed, just triggers the call)
 */
export function createLiquidateMemo(
  lendingContract: Hex,
  loanId: bigint
): string {
  const liquidateCalldata = encodeFunctionData({
    abi: SIMPLE_LENDING_ABI,
    functionName: 'liquidate',
    args: [loanId],
  })

  return createEEMMemo([
    { contract: lendingContract, calldata: liquidateCalldata, is_payable: false },
  ])
}

/**
 * Creates a memo for cancelling an unfunded loan via IBC.
 * Encodes: cancelLoan (returns collateral to borrower)
 */
export function createCancelLoanMemo(
  lendingContract: Hex,
  loanId: bigint
): string {
  const cancelLoanCalldata = encodeFunctionData({
    abi: SIMPLE_LENDING_ABI,
    functionName: 'cancelLoan',
    args: [loanId],
  })

  return createEEMMemo([
    {
      contract: lendingContract,
      calldata: cancelLoanCalldata,
      is_payable: false,
    },
  ])
}

// ============================================================================
// Utility Functions
// ============================================================================

/**
 * Get loan status from loan data
 */
export function getLoanStatus(loan: SimpleLendingLoan): LoanStatus {
  if (!loan.isActive && !loan.isFunded) {
    return 'cancelled'
  }
  if (!loan.isActive && loan.isFunded) {
    // Could be repaid or liquidated - need to check events or other state
    return 'repaid' // Default to repaid, liquidated detection would need events
  }
  if (loan.isActive && !loan.isFunded) {
    return 'unfunded'
  }
  // Active and funded
  return 'active'
}

/**
 * Format basis points as percentage string
 */
export function formatBasisPointsAsPercent(bp: bigint): string {
  const percent = Number(bp) / 100
  return `${percent}%`
}

/**
 * Format duration in seconds to human-readable string
 */
export function formatDuration(seconds: bigint): string {
  const secs = Number(seconds)
  const days = Math.floor(secs / 86400)
  const hours = Math.floor((secs % 86400) / 3600)

  if (days > 0) {
    return hours > 0 ? `${days}d ${hours}h` : `${days}d`
  }
  if (hours > 0) {
    const mins = Math.floor((secs % 3600) / 60)
    return mins > 0 ? `${hours}h ${mins}m` : `${hours}h`
  }
  const mins = Math.floor(secs / 60)
  return mins > 0 ? `${mins}m` : `${secs}s`
}

/**
 * Calculate time remaining for a loan
 */
export function calculateTimeRemaining(
  startTime: bigint,
  duration: bigint
): { isExpired: boolean; remainingSeconds: bigint; formatted: string } {
  const now = BigInt(Math.floor(Date.now() / 1000))
  const endTime = startTime + duration
  const isExpired = now > endTime
  const remainingSeconds = isExpired ? 0n : endTime - now

  return {
    isExpired,
    remainingSeconds,
    formatted: isExpired ? 'Expired' : formatDuration(remainingSeconds),
  }
}

/**
 * Validate collateral ratio (must be >= 150%)
 */
export function validateCollateralRatio(
  collateralAmount: bigint,
  loanAmount: bigint,
  minRatioBp: bigint = 15000n // 150% in basis points
): { isValid: boolean; ratioBp: bigint; formatted: string } {
  if (loanAmount === 0n) {
    return { isValid: false, ratioBp: 0n, formatted: '0%' }
  }
  const ratioBp = (collateralAmount * 10000n) / loanAmount
  const percent = Number(ratioBp) / 100
  return {
    isValid: ratioBp >= minRatioBp,
    ratioBp,
    formatted: `${percent.toFixed(1)}%`,
  }
}
